// Refile, copy and archive - one dialog, one heading or twenty, from anywhere.
//
// The three operations are one operation with three endings, so they are one
// dialog rather than three: the only things that really differ are whether a
// destination is asked for and what the button says. Three dialogs would mean
// three target pickers to keep in step, and the target picker is the whole
// difficulty.
//
// It is here rather than in any tab because the search, the file view and the
// kanban board all need it and none of them owns it - the same reason
// `SplitPane` and `recview` live where they do.
//
// Three things it is built around:
//
//  1. **The batch is one request.** A heading's hash does not survive its file
//     being edited (see `move.ts`), so twenty refiles posted one at a time
//     corrupt the batch. `ODb.move` sends the lot.
//  2. **Typing is the way to the target.** A database has hundreds of
//     headings; a tree to expand is a tree to expand every time. The box has
//     the focus on open, the arrow keys walk the list, and Enter takes the
//     highlighted one - so refiling is type-three-letters-and-Enter.
//  3. **The result is shown, not assumed.** A batch that half works is the
//     normal interesting case, and the dialog stays open to say which ones did
//     not go and why.

import * as React from 'react';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import ModalClose from '@mui/joy/ModalClose';
import Box from '@mui/joy/Box';
import Input from '@mui/joy/Input';
import Typography from '@mui/joy/Typography';
import Button from '@mui/joy/Button';
import Chip from '@mui/joy/Chip';
import Alert from '@mui/joy/Alert';
import Sheet from '@mui/joy/Sheet';
import CircularProgress from '@mui/joy/CircularProgress';
import Checkbox from '@mui/joy/Checkbox';
import SearchIcon from '@mui/icons-material/Search';
import FolderIcon from '@mui/icons-material/FolderOutlined';
import SubjectIcon from '@mui/icons-material/SubjectOutlined';
import InventoryIcon from '@mui/icons-material/Inventory2Outlined';

import { ODb } from '../db';
import {
    MoveOp, MoveNode, MoveResponse, RefileTarget,
    filterTargets, targetKey, targetLabel, targetDetail, toApiTarget,
    opTitle, opVerb, needsTarget, summarise, failures, baseName,
} from '../move';
import { useIsMobile } from '../useMobile';

export type MoveDialogProps = {
    open: boolean;
    op: MoveOp;
    nodes: MoveNode[];
    onClose: () => void;
    // Called after anything actually moved, so the caller can re-read. It is
    // given the response rather than nothing, because "two of five moved" is a
    // different refresh from "all of them did".
    onDone?: (res: MoveResponse) => void;
};

// How many headings to name before saying "and N more". Enough to check the
// selection is the one you meant, few enough not to become the dialog.
const NAMED = 6;

export default function MoveDialog({ open, op, nodes, onClose, onDone }: MoveDialogProps) {
    const isMobile = useIsMobile();
    const [targets, setTargets] = React.useState<RefileTarget[]>([]);
    const [loading, setLoading] = React.useState(false);
    const [query, setQuery] = React.useState('');
    const [picked, setPicked] = React.useState<string>('');
    const [at, setAt] = React.useState(0);
    const [create, setCreate] = React.useState(false);
    const [busy, setBusy] = React.useState(false);
    const [res, setRes] = React.useState<MoveResponse | null>(null);
    const [error, setError] = React.useState('');
    const listRef = React.useRef<HTMLDivElement>(null);

    const wantsTarget = needsTarget(op);

    // Fresh every time it opens. The targets are a picture of the database and
    // the database is what the last operation just changed.
    React.useEffect(() => {
        if (!open) return;
        setQuery(''); setPicked(''); setAt(0); setRes(null); setError(''); setCreate(false);
        if (!wantsTarget) return;
        let gone = false;
        setLoading(true);
        ODb.refileTargets(4)
            .then(r => { if (!gone) setTargets((r && r.Targets) || []); })
            .catch(e => { if (!gone) setError((e && e.message) || 'Could not read the targets.'); })
            .finally(() => { if (!gone) setLoading(false); });
        return () => { gone = true; };
    }, [open, wantsTarget]);

    const shown = React.useMemo(() => filterTargets(targets, query, 300), [targets, query]);

    // The highlight follows the list rather than the other way round: filtering
    // to three rows with the cursor on the twentieth would leave Enter doing
    // nothing, which reads as the dialog being broken.
    React.useEffect(() => { setAt(0); }, [query]);
    React.useEffect(() => {
        if (shown.length === 0) { setPicked(''); return; }
        const i = Math.max(0, Math.min(at, shown.length - 1));
        setPicked(targetKey(shown[i]));
    }, [shown, at]);

    // Keep the highlighted row on screen while the arrows walk past the fold.
    React.useEffect(() => {
        const el = listRef.current?.querySelector('[data-at="1"]');
        if (el) (el as HTMLElement).scrollIntoView({ block: 'nearest' });
    }, [at, shown]);

    const target = React.useMemo(
        () => shown.find(t => targetKey(t) === picked) || null, [shown, picked]);

    const go = React.useCallback(async () => {
        if (busy) return;
        if (wantsTarget && !target) return;
        setBusy(true); setError('');
        try {
            const r = await ODb.move(
                op,
                nodes.map(n => n.hash),
                wantsTarget && target ? toApiTarget(target) : null,
                create,
            );
            setRes(r);
            if (r && (r.Done > 0 || r.Skipped > 0)) onDone?.(r);
            // Nothing went wrong and nothing is left to look at: get out of the
            // way. A dialog that stays open on a clean result is a dialog you
            // have to dismiss every time.
            if (r && r.Failed === 0 && r.Done > 0) {
                setTimeout(() => onClose(), 650);
            }
        } catch (e: any) {
            setError((e && e.message) || 'That did not work.');
        }
        setBusy(false);
    }, [busy, wantsTarget, target, op, nodes, create, onDone, onClose]);

    const onKey = (e: React.KeyboardEvent) => {
        if (e.key === 'ArrowDown') { e.preventDefault(); setAt(i => Math.min(i + 1, shown.length - 1)); }
        else if (e.key === 'ArrowUp') { e.preventDefault(); setAt(i => Math.max(i - 1, 0)); }
        else if (e.key === 'Enter') { e.preventDefault(); go(); }
    };

    const summary = res ? summarise(res, op) : null;
    const bad = res ? failures(res) : [];

    return (
        <Modal open={open} onClose={onClose}>
            <ModalDialog
                sx={{
                    width: isMobile ? '96vw' : 620,
                    maxWidth: '96vw',
                    maxHeight: '88vh',
                    display: 'flex',
                    flexDirection: 'column',
                    p: 2,
                }}
            >
                <ModalClose />
                <Typography level="title-md" sx={{ pr: 4 }}>{opTitle(op, nodes.length)}</Typography>

                {/* What is being moved. Named rather than counted, because the
                    commonest mistake here is having the wrong things selected
                    and a number cannot show you that. */}
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mt: 1, mb: 1.5 }}>
                    {nodes.slice(0, NAMED).map((n, i) => (
                        <Chip key={n.hash + i} size="sm" variant="soft" color="neutral">
                            {n.headline}
                        </Chip>
                    ))}
                    {nodes.length > NAMED && (
                        <Chip size="sm" variant="plain" color="neutral">
                            and {nodes.length - NAMED} more
                        </Chip>
                    )}
                </Box>

                {/* Archive is told nothing: org works the destination out of the
                    heading's own :ARCHIVE:, then the file's #+ARCHIVE:, then the
                    server's default. Saying so beats a picker that is ignored. */}
                {!wantsTarget && (
                    <Alert size="sm" variant="soft" color="neutral" startDecorator={<InventoryIcon />} sx={{ mb: 1.5 }}>
                        <Box>
                            <Typography level="body-sm">
                                Each heading goes where its own file says to put it.
                            </Typography>
                            <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                                Its <code>:ARCHIVE:</code> property, then the file's <code>#+ARCHIVE:</code>,
                                then the server's default. The outline path, the keyword and the time are
                                kept on the archived copy.
                            </Typography>
                        </Box>
                    </Alert>
                )}

                {wantsTarget && (
                    <>
                        <Input
                            autoFocus
                            size="sm"
                            value={query}
                            onChange={e => setQuery(e.target.value)}
                            onKeyDown={onKey}
                            placeholder="Where to? Type part of a heading or a file"
                            startDecorator={<SearchIcon />}
                            sx={{ mb: 1 }}
                        />
                        <Sheet
                            ref={listRef}
                            variant="outlined"
                            sx={{ flex: 1, minHeight: 140, maxHeight: 320, overflowY: 'auto', borderRadius: 'sm' }}
                        >
                            {loading && <Box sx={{ p: 2 }}><CircularProgress size="sm" /></Box>}
                            {!loading && shown.length === 0 && (
                                <Typography level="body-sm" sx={{ p: 2, color: 'text.tertiary' }}>
                                    {targets.length === 0
                                        ? 'No targets — check the server’s refileTargets setting.'
                                        : 'Nothing matches that.'}
                                </Typography>
                            )}
                            {shown.map((t, i) => {
                                const on = targetKey(t) === picked;
                                return (
                                    <Box
                                        key={targetKey(t) + i}
                                        data-at={i === at ? '1' : undefined}
                                        onClick={() => { setAt(i); setPicked(targetKey(t)); }}
                                        onDoubleClick={() => { setAt(i); setPicked(targetKey(t)); go(); }}
                                        sx={{
                                            display: 'flex', alignItems: 'center', gap: 1,
                                            px: 1.25, py: isMobile ? 1 : 0.6,
                                            cursor: 'pointer',
                                            bgcolor: on ? 'primary.softBg' : 'transparent',
                                            '&:hover': { bgcolor: on ? 'primary.softBg' : 'background.level1' },
                                            borderBottom: '1px solid', borderColor: 'divider',
                                            '&:last-child': { borderBottom: 'none' },
                                        }}
                                    >
                                        {(t.Olp || []).length === 0
                                            ? <FolderIcon sx={{ fontSize: 16, color: 'text.tertiary', flexShrink: 0 }} />
                                            : <SubjectIcon sx={{ fontSize: 16, color: 'text.tertiary', flexShrink: 0 }} />}
                                        <Box sx={{ minWidth: 0, flex: 1 }}>
                                            <Typography level="body-sm" noWrap sx={{ fontWeight: on ? 'lg' : 'md' }}>
                                                {targetLabel(t)}
                                            </Typography>
                                            <Typography level="body-xs" noWrap sx={{ color: 'text.tertiary' }}>
                                                {targetDetail(t)}
                                            </Typography>
                                        </Box>
                                        {t.Todo && (
                                            <Chip size="sm" variant="soft" color="primary">{t.Todo}</Chip>
                                        )}
                                    </Box>
                                );
                            })}
                        </Sheet>
                    </>
                )}

                {error !== '' && (
                    <Alert size="sm" color="danger" variant="soft" sx={{ mt: 1.5 }}>{error}</Alert>
                )}

                {/* What happened. It stays up when anything failed, because
                    "two of five moved" is the case somebody has to act on. */}
                {summary && (
                    <Alert size="sm" color={summary.tone} variant="soft" sx={{ mt: 1.5 }}>
                        <Box sx={{ minWidth: 0 }}>
                            <Typography level="body-sm">{summary.text}</Typography>
                            {bad.map((r, i) => (
                                <Typography key={i} level="body-xs" sx={{ display: 'block' }}>
                                    {r.Headline} — {r.Msg}
                                </Typography>
                            ))}
                        </Box>
                    </Alert>
                )}

                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 1.5 }}>
                    {wantsTarget && (
                        <Checkbox
                            size="sm"
                            label="Make it if it is not there"
                            checked={create}
                            onChange={e => setCreate(e.target.checked)}
                        />
                    )}
                    <Box sx={{ flex: 1 }} />
                    <Button size="sm" variant="plain" color="neutral" onClick={onClose}>
                        {res ? 'Close' : 'Cancel'}
                    </Button>
                    <Button
                        size="sm"
                        color={op === 'archive' ? 'warning' : 'primary'}
                        loading={busy}
                        disabled={nodes.length === 0 || (wantsTarget && !target)}
                        onClick={go}
                    >
                        {opVerb(op)}
                        {wantsTarget && target ? ` to ${baseName(targetLabel(target))}` : ''}
                    </Button>
                </Box>
            </ModalDialog>
        </Modal>
    );
}
