// The gantt chart's smaller controls, kept out of GanttChart.tsx: the presets
// panel, the baseline menu and the right click menu on a bar. Each holds no
// state of the chart's own - it is handed what it shows and says what changed.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Button from '@mui/joy/Button';
import IconButton from '@mui/joy/IconButton';
import Switch from '@mui/joy/Switch';
import Input from '@mui/joy/Input';
import Divider from '@mui/joy/Divider';
import Tooltip from '@mui/joy/Tooltip';
import Popper from '@mui/material/Popper';
import ClickAwayListener from '@mui/material/ClickAwayListener';
import AutoAwesomeIcon from '@mui/icons-material/AutoAwesomeOutlined';
import HistoryIcon from '@mui/icons-material/HistoryOutlined';
import DeleteIcon from '@mui/icons-material/DeleteOutline';
import BrushIcon from '@mui/icons-material/BrushOutlined';
import EditIcon from '@mui/icons-material/EditOutlined';
import { PRESETS, PresetState, applyDesign } from '../ganttpresets';
import { GanttBaseline } from '../gantt';
import { GanttTask } from '../gantt';

// A panel hung off a button, closed by clicking anywhere else. The button
// must not stop its click propagating, or the panel's own click-away never
// hears the click that should close it (see the search tab's notes).
export function Panel({ anchor, open, onClose, children, width = 340 }: {
    anchor: HTMLElement | null; open: boolean; onClose: () => void; children: React.ReactNode; width?: number;
}) {
    return (
        <Popper
            open={open && !!anchor}
            anchorEl={anchor}
            placement="bottom-start"
            modifiers={[
                { name: 'offset', options: { offset: [0, 6] } },
                { name: 'preventOverflow', options: { padding: 8, altAxis: true } },
                { name: 'flip', options: { padding: 8 } },
            ]}
            style={{ zIndex: 1300 }}
        >
            <ClickAwayListener onClickAway={onClose}>
                <Sheet
                    variant="outlined"
                    sx={{ borderRadius: 'md', boxShadow: 'lg', p: 1.25, width, maxHeight: '70vh', overflowY: 'auto' }}
                >
                    {children}
                </Sheet>
            </ClickAwayListener>
        </Popper>
    );
}

// --- presets -----------------------------------------------------------------

export function PresetsButton({ state, onChange, disabled }: {
    state: PresetState;
    onChange: (next: PresetState) => void;
    disabled?: boolean;
}) {
    const [anchor, setAnchor] = React.useState<HTMLElement | null>(null);
    const [open, setOpen] = React.useState(false);
    const onCount = PRESETS.filter(p => p.on(state)).length;
    return (
        <>
            <Button
                size="sm" variant="outlined" disabled={disabled}
                startDecorator={<AutoAwesomeIcon />}
                ref={el => setAnchor(el)}
                onClick={() => setOpen(o => !o)}
            >
                {onCount > 0 ? `Presets (${onCount})` : 'Presets'}
            </Button>
            <Panel anchor={anchor} open={open} onClose={() => setOpen(false)} width={360}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                    <Box sx={{ flex: 1 }}>
                        <Typography level="title-sm">Presets</Typography>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            Switching one off takes back only what it added.
                        </Typography>
                    </Box>
                    <Tooltip size="sm" title="Lanes by ASSIGNED, milestone markers, blocked outlined, unscheduled and submitted hatched">
                        <Button size="sm" onClick={() => onChange(applyDesign(state))}>Design</Button>
                    </Tooltip>
                </Box>
                <Divider sx={{ mb: 0.5 }} />
                {PRESETS.map(p => {
                    const on = p.on(state);
                    return (
                        <Box
                            key={p.id}
                            sx={{ display: 'flex', alignItems: 'center', gap: 1, py: 0.6 }}
                        >
                            <Box sx={{ flex: 1, minWidth: 0 }}>
                                <Typography level="body-sm">
                                    {p.label}
                                    {p.design && (
                                        <Typography component="span" level="body-xs" sx={{ color: 'primary.500', ml: 0.75 }}>
                                            design
                                        </Typography>
                                    )}
                                </Typography>
                                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{p.hint}</Typography>
                            </Box>
                            <Switch
                                size="sm" checked={on}
                                onChange={e => onChange(e.target.checked ? p.add(state) : p.remove(state))}
                            />
                        </Box>
                    );
                })}
            </Panel>
        </>
    );
}

// --- baselines ----------------------------------------------------------------

function whenTaken(iso: string): string {
    const d = new Date(iso);
    return isNaN(d.getTime()) ? iso : d.toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' });
}

export function BaselineButton({ baselines, shown, canTake, onTake, onShow, onDelete, disabled }: {
    baselines: GanttBaseline[];
    shown: string;
    // Why a snapshot cannot be taken now, or '' when it can.
    canTake: string;
    onTake: (name: string) => void;
    onShow: (name: string) => void;
    onDelete: (name: string) => void;
    disabled?: boolean;
}) {
    const [anchor, setAnchor] = React.useState<HTMLElement | null>(null);
    const [open, setOpen] = React.useState(false);
    const today = new Date().toISOString().slice(0, 10);
    const [name, setName] = React.useState('');
    React.useEffect(() => { if (open) setName(`Baseline ${today}`); }, [open, today]);
    const taken = baselines.some(b => b.name === name.trim());
    return (
        <>
            <Button
                size="sm" variant={shown ? 'soft' : 'outlined'} disabled={disabled}
                startDecorator={<HistoryIcon />}
                ref={el => setAnchor(el)}
                onClick={() => setOpen(o => !o)}
            >
                {shown ? `Baseline: ${shown}` : 'Baseline'}
            </Button>
            <Panel anchor={anchor} open={open} onClose={() => setOpen(false)} width={360}>
                <Typography level="title-sm">Baselines</Typography>
                <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 1 }}>
                    A snapshot of every bar's dates, drawn as a ghost under the bars so you can see what
                    has moved since. Kept with the view.
                </Typography>
                <Box sx={{ display: 'flex', gap: 1, mb: 1 }}>
                    <Input
                        size="sm" value={name} onChange={e => setName(e.target.value)} sx={{ flex: 1 }}
                        onKeyDown={e => { if (e.key === 'Enter' && name.trim() && !canTake && !taken) onTake(name.trim()); }}
                    />
                    <Button size="sm" disabled={!name.trim() || !!canTake || taken}
                        onClick={() => onTake(name.trim())}>
                        Take snapshot
                    </Button>
                </Box>
                {canTake && <Typography level="body-xs" sx={{ color: 'warning.600', mb: 1 }}>{canTake}</Typography>}
                {taken && <Typography level="body-xs" sx={{ color: 'warning.600', mb: 1 }}>A baseline has that name already.</Typography>}
                <Divider sx={{ mb: 0.5 }} />
                <Box
                    sx={{ display: 'flex', alignItems: 'center', gap: 1, py: 0.5, cursor: 'pointer', borderRadius: 'sm', px: 0.5,
                        bgcolor: !shown ? 'neutral.softBg' : undefined }}
                    onClick={() => onShow('')}
                >
                    <Typography level="body-sm" sx={{ flex: 1 }}>No baseline</Typography>
                </Box>
                {baselines.length === 0 && (
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', py: 0.5 }}>No snapshots yet.</Typography>
                )}
                {baselines.map(b => (
                    <Box
                        key={b.name}
                        sx={{ display: 'flex', alignItems: 'center', gap: 1, py: 0.5, px: 0.5, borderRadius: 'sm', cursor: 'pointer',
                            bgcolor: shown === b.name ? 'primary.softBg' : undefined }}
                        onClick={() => onShow(b.name)}
                    >
                        <Box sx={{ flex: 1, minWidth: 0 }}>
                            <Typography level="body-sm">{b.name}</Typography>
                            <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                                {`${whenTaken(b.taken)} · ${b.tasks.length} task${b.tasks.length === 1 ? '' : 's'}`}
                            </Typography>
                        </Box>
                        <Tooltip size="sm" title={`Delete ${b.name}`}>
                            <IconButton size="sm" variant="plain" color="danger"
                                onClick={e => { e.stopPropagation(); onDelete(b.name); }}>
                                <DeleteIcon />
                            </IconButton>
                        </Tooltip>
                    </Box>
                ))}
            </Panel>
        </>
    );
}

// --- the right click menu on a bar --------------------------------------------

export function BarMenu({ at, task, onClose, onStyle, onEdit }: {
    at: { x: number; y: number } | null;
    task: GanttTask | null;
    onClose: () => void;
    onStyle: (t: GanttTask) => void;
    onEdit: (t: GanttTask) => void;
}) {
    // Anchored to an invisible box at the pointer, since a bar in an svg (or
    // inside vis) is not an element the popper can sit against.
    const [anchor, setAnchor] = React.useState<HTMLElement | null>(null);
    React.useEffect(() => {
        if (!at) return;
        const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
        window.addEventListener('keydown', onKey);
        return () => window.removeEventListener('keydown', onKey);
    }, [at, onClose]);
    if (!at || !task) return null;
    const item = (icon: React.ReactNode, label: string, run: () => void) => (
        <Box
            role="menuitem"
            tabIndex={0}
            onClick={() => { onClose(); run(); }}
            onKeyDown={e => { if (e.key === 'Enter') { onClose(); run(); } }}
            sx={{
                display: 'flex', alignItems: 'center', gap: 1, px: 1, py: 0.75, borderRadius: 'sm', cursor: 'pointer',
                '&:hover, &:focus-visible': { bgcolor: 'neutral.softHoverBg', outline: 'none' },
            }}
        >
            {icon}
            <Typography level="body-sm">{label}</Typography>
        </Box>
    );
    return (
        <>
            <div ref={setAnchor} style={{ position: 'fixed', left: at.x, top: at.y, width: 1, height: 1 }} />
            <Panel anchor={anchor} open={true} onClose={onClose} width={250}>
                <Typography level="body-xs" sx={{ color: 'text.tertiary', px: 1, pb: 0.5 }} noWrap>
                    {task.name}
                </Typography>
                {item(<BrushIcon fontSize="small" />, 'Style headings like this…', () => onStyle(task))}
                {item(<EditIcon fontSize="small" />, 'Edit in the panel', () => onEdit(task))}
            </Panel>
        </>
    );
}

// A toolbar button that opens a small panel under itself: the options menu,
// the dates menu, the export menu. The panel is handed a close function so a
// choice that finishes the job can put it away.
export function PanelButton({ label, icon, title, children, width = 280, variant = 'outlined', disabled, badge }: {
    label?: React.ReactNode;
    icon?: React.ReactNode;
    title?: string;
    children: (close: () => void) => React.ReactNode;
    width?: number;
    variant?: 'outlined' | 'soft' | 'plain';
    disabled?: boolean;
    // A dot on the button: something in the panel is switched on.
    badge?: boolean;
}) {
    const [anchor, setAnchor] = React.useState<HTMLElement | null>(null);
    const [open, setOpen] = React.useState(false);
    const close = React.useCallback(() => setOpen(false), []);
    const button = label !== undefined ? (
        <Button size="sm" variant={variant} startDecorator={icon} disabled={disabled}
            ref={el => setAnchor(el)} onClick={() => setOpen(o => !o)} aria-haspopup="dialog" aria-expanded={open}>
            {label}
        </Button>
    ) : (
        <IconButton size="sm" variant={variant} disabled={disabled} aria-label={title}
            ref={el => setAnchor(el)} onClick={() => setOpen(o => !o)} aria-haspopup="dialog" aria-expanded={open}>
            {icon}
        </IconButton>
    );
    return (
        <>
            <Tooltip size="sm" title={open ? '' : (title || '')}>
                <span style={{ position: 'relative', display: 'inline-flex' }}>
                    {button}
                    {badge && (
                        <Box sx={{
                            position: 'absolute', top: -2, right: -2, width: 8, height: 8, borderRadius: '50%',
                            bgcolor: 'primary.500', border: '1.5px solid', borderColor: 'background.surface', pointerEvents: 'none',
                        }} />
                    )}
                </span>
            </Tooltip>
            <Panel anchor={anchor} open={open} onClose={close} width={width}>
                {children(close)}
            </Panel>
        </>
    );
}

// A small menu at a point on the screen - the right click on empty chart.
// Anchored like BarMenu, to an invisible box at the pointer.
export function PointMenu({ at, title, items, onClose }: {
    at: { x: number; y: number } | null;
    title?: string;
    items: { icon: React.ReactNode; label: string; run: () => void }[];
    onClose: () => void;
}) {
    const [anchor, setAnchor] = React.useState<HTMLElement | null>(null);
    React.useEffect(() => {
        if (!at) return;
        const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
        window.addEventListener('keydown', onKey);
        return () => window.removeEventListener('keydown', onKey);
    }, [at, onClose]);
    if (!at) return null;
    return (
        <>
            <div ref={setAnchor} style={{ position: 'fixed', left: at.x, top: at.y, width: 1, height: 1 }} />
            <Panel anchor={anchor} open={true} onClose={onClose} width={250}>
                {title && (
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', px: 1, pb: 0.5 }} noWrap>{title}</Typography>
                )}
                {items.map((it, i) => (
                    <Box
                        key={i}
                        role="menuitem"
                        tabIndex={0}
                        onClick={() => { onClose(); it.run(); }}
                        onKeyDown={e => { if (e.key === 'Enter') { onClose(); it.run(); } }}
                        sx={{
                            display: 'flex', alignItems: 'center', gap: 1, px: 1, py: 0.75, borderRadius: 'sm', cursor: 'pointer',
                            '&:hover, &:focus-visible': { bgcolor: 'neutral.softHoverBg', outline: 'none' },
                        }}
                    >
                        {it.icon}
                        <Typography level="body-sm">{it.label}</Typography>
                    </Box>
                ))}
            </Panel>
        </>
    );
}
