// Where a new marker can go, and finding one by typing. Kept out of the
// dialog so the ranking - which decides whether the place you meant is the
// first thing under the cursor among hundreds of files - is tested.

import { fuzzyScoreAll, fuzzyTerms } from './fuzzy';

export interface Place {
    // p:<hash> puts it under that heading; f:<path> at the end of that file.
    value: string;
    // What is matched loosely and shown first: a heading's title or a file's
    // name.
    name: string;
    // The rest, matched on whole words: the path, the file a heading is in.
    hint: string;
    // How it reads in the list: "Beside Kickoff", "Under Milestones", "End of plan.org".
    label: string;
}

export function baseName(p: string): string {
    const i = p.lastIndexOf('/');
    return i >= 0 ? p.slice(i + 1) : p;
}

export function filePlace(path: string): Place {
    return { value: `f:${path}`, name: baseName(path), hint: path, label: `End of ${baseName(path)}` };
}

export function headingPlace(hash: string, title: string, file: string): Place {
    return { value: `p:${hash}`, name: title, hint: file, label: `Under ${title}` };
}

// The places in the order to show them for what has been typed: best match
// first, the order given breaking ties (so places near the chart's own
// markers, listed first, win a tie with a file somewhere else). With nothing
// typed, the list as given.
export function rankPlaces(places: Place[], filter: string, max = 50): Place[] {
    const terms = fuzzyTerms(filter);
    if (terms.length === 0) return places.slice(0, max);
    const hits: { p: Place; score: number; i: number }[] = [];
    places.forEach((p, i) => {
        const score = fuzzyScoreAll(terms, p.name, `${p.name} ${p.hint}`);
        if (score !== null) hits.push({ p, score, i });
    });
    hits.sort((a, b) => (b.score - a.score) || (a.i - b.i));
    return hits.slice(0, max).map(h => h.p);
}

// One place per value, the first kept: a file can be both "where the chart's
// tasks are" and in the full list of files.
export function uniquePlaces(places: Place[]): Place[] {
    const seen = new Set<string>();
    return places.filter(p => (seen.has(p.value) ? false : (seen.add(p.value), true)));
}
