// The command palette: one box, everything worth reaching.
//
// It opens on ⌘K / ctrl-K anywhere in worg and answers the two questions a
// palette is for - "take me there" and "do this" - without the reader knowing
// which tab a thing lives in. What it offers is built fresh each time it opens:
// the panels, the capture templates, every org file, the saved searches, the
// kanban boards and the collections. Headings are different, and are asked for
// as you type, because there are thousands of them and the server already knows
// how to find one.
//
// Two things about it are deliberate. The matcher is `fuzzy.ts`, which is the
// one the terminal chooser uses, so the letters that find a thing in one find
// it in the other. And what you pick is remembered (`noteUse`), so the second
// use of the palette is faster than the first - which is the whole difference
// between a palette people open and one they forget about.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Modal from '@mui/joy/Modal';
import Sheet from '@mui/joy/Sheet';
import Input from '@mui/joy/Input';
import Typography from '@mui/joy/Typography';
import Chip from '@mui/joy/Chip';
import CircularProgress from '@mui/joy/CircularProgress';
import SearchIcon from '@mui/icons-material/Search';
import ArrowForwardIcon from '@mui/icons-material/ArrowForwardOutlined';
import EditNoteIcon from '@mui/icons-material/EditNote';
import DescriptionIcon from '@mui/icons-material/DescriptionOutlined';
import BookmarkIcon from '@mui/icons-material/BookmarkOutlined';
import ViewKanbanIcon from '@mui/icons-material/ViewKanbanOutlined';
import ViewTimelineIcon from '@mui/icons-material/ViewTimelineOutlined';
import InventoryIcon from '@mui/icons-material/Inventory2Outlined';
import SubjectIcon from '@mui/icons-material/SubjectOutlined';
import TuneIcon from '@mui/icons-material/TuneOutlined';

import { ODb } from '../db';
import { useSetting } from '../useSettings';
import { useColorScheme } from '@mui/joy/styles';
import {
    Command, CommandKind, PANELS, rankCommands, paletteLines,
    loadRecents, noteUse, headlineQuery,
} from '../palette';

// What the palette can do to the rest of the app. All of it is App's to do -
// the panels are siblings and this is not one of them - so it arrives as a set
// of callbacks rather than being reached for.
export type PaletteActions = {
    go: (app: string) => void;
    capture: (template?: string) => void;
    openFile: (filename: string, line?: number, heading?: string) => void;
    runQuery: (query: string) => void;
    openBoard: (name: string) => void;
    openGanttView: (name: string) => void;
    openCollection: (name: string) => void;
};

const KIND_ICON: Record<CommandKind, React.ReactNode> = {
    go: <ArrowForwardIcon fontSize="small" />,
    capture: <EditNoteIcon fontSize="small" />,
    file: <DescriptionIcon fontSize="small" />,
    query: <BookmarkIcon fontSize="small" />,
    board: <ViewKanbanIcon fontSize="small" />,
    gantt: <ViewTimelineIcon fontSize="small" />,
    collection: <InventoryIcon fontSize="small" />,
    heading: <SubjectIcon fontSize="small" />,
    action: <TuneIcon fontSize="small" />,
};

// The file, said the way the rest of worg says one: the name you read, the
// path kept for the second line.
function baseName(path: string): string {
    const parts = (path || '').split(/[\\/]/);
    return parts[parts.length - 1] || path;
}

export default function Palette({
    open,
    onClose,
    actions,
    activeApp,
}: {
    open: boolean;
    onClose: () => void;
    actions: PaletteActions;
    activeApp: string;
}) {
    const [filter, setFilter] = React.useState('');
    const [cursor, setCursor] = React.useState(0);
    const [recents, setRecents] = React.useState<string[]>([]);
    const [files, setFiles] = React.useState<string[]>([]);
    const [templates, setTemplates] = React.useState<string[]>([]);
    const [queries, setQueries] = React.useState<{ name: string; query: string }[]>([]);
    const [boards, setBoards] = React.useState<string[]>([]);
    const [ganttViews, setGanttViews] = React.useState<string[]>([]);
    const [collections, setCollections] = React.useState<string[]>([]);
    const [headings, setHeadings] = React.useState<any[]>([]);
    const [looking, setLooking] = React.useState(false);

    const { mode, systemMode, setMode } = useColorScheme();
    const dark = (mode === 'system' ? systemMode : mode) !== 'light';
    const [showFile, setShowFile] = useSetting('searchShowFile');
    const [groupByFile, setGroupByFile] = useSetting('searchGroupByFile');
    const [searchRecords, setSearchRecords] = useSetting('searchRecords');
    const [fileView, setFileView] = useSetting('fileView');

    const listRef = React.useRef<HTMLDivElement | null>(null);

    // Everything the palette offers is read when it opens rather than kept up
    // to date behind it: these are small lists, it is a moment's work, and a
    // palette that offers a file somebody deleted an hour ago is worse than one
    // that takes 40ms to open. A source that fails is simply not offered - the
    // palette is still worth having without the boards in it.
    React.useEffect(() => {
        if (!open) return;
        setRecents(loadRecents());
        let gone = false;
        const load = async () => {
            const [f, t, q, b, c, g] = await Promise.all([
                ODb.getFiles().catch(() => [] as string[]),
                ODb.captureTemplates().catch(() => [] as any[]),
                ODb.getStoredQueries().catch(() => [] as any[]),
                ODb.getKanbanBoards().catch(() => [] as any[]),
                ODb.recordCollections().catch(() => [] as any[]),
                ODb.getGanttViews().catch(() => [] as any[]),
            ]);
            if (gone) return;
            setFiles(Array.isArray(f) ? f : []);
            setTemplates((Array.isArray(t) ? t : []).map((x: any) => x.Name || x.name).filter(Boolean));
            setQueries((Array.isArray(q) ? q : []).filter((x: any) => x && x.name));
            setBoards((Array.isArray(b) ? b : []).map((x: any) => x.Name || x.name).filter(Boolean));
            setGanttViews((Array.isArray(g) ? g : []).map((x: any) => x.name).filter(Boolean));
            setCollections((Array.isArray(c) ? c : []).map((x: any) => x.Type || x.name).filter(Boolean));
        };
        load();
        return () => { gone = true; };
    }, [open]);

    // The box starts empty every time. A palette that opens on what you typed
    // last is a palette you have to clear before you can use it.
    React.useEffect(() => {
        if (open) { setFilter(''); setCursor(0); setHeadings([]); }
    }, [open]);

    // Headings are asked for rather than held: there are thousands of them and
    // this is the one thing the server is better placed to answer. Debounced,
    // and every request carries the abort of the one before it, so a fast
    // typist gets one answer rather than eight out of order.
    React.useEffect(() => {
        const text = filter.trim();
        if (!open || text.length < 2) { setHeadings([]); setLooking(false); return; }
        const ctrl = new AbortController();
        setLooking(true);
        const t = window.setTimeout(async () => {
            try {
                const rows = await ODb.query(headlineQuery(text), false, ctrl.signal, '!IsArchived()');
                if (!ctrl.signal.aborted) setHeadings(Array.isArray(rows) ? rows.slice(0, 12) : []);
            } catch {
                if (!ctrl.signal.aborted) setHeadings([]);
            }
            if (!ctrl.signal.aborted) setLooking(false);
        }, 180);
        return () => { window.clearTimeout(t); ctrl.abort(); };
    }, [filter, open]);

    const commands = React.useMemo<Command[]>(() => {
        const out: Command[] = [];

        for (const p of PANELS) {
            if (p.app === activeApp) continue;   // you are already here
            out.push({
                id: `go:${p.app}`, kind: 'go', name: p.name, hint: p.hint,
                run: () => actions.go(p.app),
            });
        }

        out.push({
            id: 'capture:', kind: 'capture', name: 'Capture something',
            hint: 'file a note, a task, a thought', keys: 'c',
            run: () => actions.capture(),
        });
        for (const t of templates) {
            out.push({
                id: `capture:${t}`, kind: 'capture', name: `Capture: ${t}`,
                hint: 'straight into this template', run: () => actions.capture(t),
            });
        }

        for (const f of files) {
            out.push({
                id: `file:${f}`, kind: 'file', name: baseName(f), hint: f,
                run: () => actions.openFile(f),
            });
        }

        for (const q of queries) {
            out.push({
                id: `query:${q.name}`, kind: 'query', name: q.name, hint: q.query,
                run: () => actions.runQuery(q.query),
            });
        }

        for (const b of boards) {
            out.push({
                id: `board:${b}`, kind: 'board', name: b, hint: 'kanban board',
                run: () => actions.openBoard(b),
            });
        }

        for (const g of ganttViews) {
            out.push({
                id: `gantt:${g}`, kind: 'gantt', name: g, hint: 'gantt chart view',
                run: () => actions.openGanttView(g),
            });
        }

        for (const c of collections) {
            out.push({
                id: `collection:${c}`, kind: 'collection', name: c, hint: 'collection of records',
                run: () => actions.openCollection(c),
            });
        }

        // Headings come back ranked by the server's own match, and are left in
        // that order: they are already an answer to what was typed.
        for (const h of headings) {
            const file = h.Filename || '';
            out.push({
                id: `heading:${h.Hash}`, kind: 'heading', name: h.Headline || '(no headline)',
                hint: `${baseName(file)}${h.LineNum !== undefined ? `:${h.LineNum + 1}` : ''}`,
                run: () => actions.openFile(file, h.LineNum, h.Headline),
            });
        }

        out.push(
            {
                id: 'action:mode', kind: 'action',
                name: dark ? 'Switch to the light theme' : 'Switch to the dark theme',
                hint: 'light and dark mode',
                run: () => setMode(dark ? 'light' : 'dark'),
            },
            {
                id: 'action:searchShowFile', kind: 'action',
                name: `${showFile ? 'Hide' : 'Show'} filenames under search results`,
                hint: 'search tab', run: () => setShowFile(!showFile),
            },
            {
                id: 'action:searchGroupByFile', kind: 'action',
                name: `${groupByFile ? 'Stop grouping' : 'Group'} search results by file`,
                hint: 'search tab', run: () => setGroupByFile(!groupByFile),
            },
            {
                id: 'action:searchRecords', kind: 'action',
                name: `${searchRecords ? 'Leave records out of' : 'Include records in'} searches`,
                hint: 'contacts and collections', run: () => setSearchRecords(!searchRecords),
            },
            {
                id: 'action:fileView', kind: 'action',
                name: fileView === 'source' ? 'Read files as the rendered page' : 'Read files as org text',
                hint: 'files tab', run: () => setFileView(fileView === 'source' ? 'html' : 'source'),
            },
            {
                id: 'action:reload', kind: 'action', name: 'Reload worg',
                hint: 'fetch the page again', run: () => window.location.reload(),
            },
        );
        return out;
    }, [
        activeApp, actions, templates, files, queries, boards, ganttViews, collections, headings,
        dark, setMode, showFile, setShowFile, groupByFile, setGroupByFile,
        searchRecords, setSearchRecords, fileView, setFileView,
    ]);

    const ranked = React.useMemo(
        () => rankCommands(commands, filter, recents), [commands, filter, recents]);
    const filtered = filter.trim() !== '';
    const recentCount = filtered ? 0 : ranked.filter(c => recents.includes(c.id)).length;
    const lines = React.useMemo(
        () => paletteLines(ranked, filtered, recentCount), [ranked, filtered, recentCount]);

    // The cursor is an index into the commands, not into the lines, so a band
    // can never be landed on.
    React.useEffect(() => { setCursor(0); }, [filter]);
    React.useEffect(() => {
        if (cursor >= ranked.length) setCursor(Math.max(0, ranked.length - 1));
    }, [ranked, cursor]);

    const choose = React.useCallback((c: Command) => {
        setRecents(r => noteUse(c.id, c.kind, r));
        onClose();
        // After the dialog has gone: a command that moves the reader to another
        // panel should not be doing it underneath an open palette.
        window.setTimeout(() => c.run(), 0);
    }, [onClose]);

    const onKey = (e: React.KeyboardEvent) => {
        if (e.key === 'ArrowDown' || (e.ctrlKey && e.key === 'n')) {
            e.preventDefault();
            setCursor(i => Math.min(i + 1, ranked.length - 1));
        } else if (e.key === 'ArrowUp' || (e.ctrlKey && e.key === 'p')) {
            e.preventDefault();
            setCursor(i => Math.max(i - 1, 0));
        } else if (e.key === 'Home') {
            e.preventDefault(); setCursor(0);
        } else if (e.key === 'End') {
            e.preventDefault(); setCursor(Math.max(0, ranked.length - 1));
        } else if (e.key === 'Enter') {
            e.preventDefault();
            const c = ranked[cursor];
            if (c) choose(c);
        } else if (e.key === 'Escape') {
            e.preventDefault(); onClose();
        }
    };

    // Keep the cursor on screen. The list is long and the keyboard is how it is
    // meant to be walked, so scrolling it by hand is not an option.
    React.useEffect(() => {
        const el = listRef.current?.querySelector(`[data-cmd-index="${cursor}"]`);
        if (el) (el as HTMLElement).scrollIntoView({ block: 'nearest' });
    }, [cursor, lines]);

    let index = -1;

    return (
        <Modal open={open} onClose={onClose}>
            <Box
                sx={{
                    position: 'fixed', inset: 0, display: 'flex',
                    justifyContent: 'center', alignItems: 'flex-start',
                    pt: '10vh', px: 2, pointerEvents: 'none',
                }}
            >
                <Sheet
                    variant="outlined"
                    sx={{
                        pointerEvents: 'auto',
                        width: 'min(680px, 100%)', borderRadius: 'lg',
                        boxShadow: 'lg', overflow: 'hidden',
                        display: 'flex', flexDirection: 'column', maxHeight: '70vh',
                    }}
                    onKeyDown={onKey}
                >
                    <Input
                        autoFocus
                        value={filter}
                        onChange={e => setFilter(e.target.value)}
                        placeholder="Go somewhere, capture something, find a heading…"
                        variant="plain"
                        size="lg"
                        startDecorator={<SearchIcon />}
                        endDecorator={looking ? <CircularProgress size="sm" /> : null}
                        sx={{
                            '--Input-focusedThickness': '0px',
                            borderRadius: 0, borderBottom: '1px solid',
                            borderColor: 'divider', fontSize: 16,
                        }}
                    />
                    <Box ref={listRef} sx={{ overflowY: 'auto', py: 0.5 }}>
                        {lines.length === 0 && (
                            <Typography level="body-sm" sx={{ p: 2, color: 'text.tertiary' }}>
                                Nothing matches that.
                            </Typography>
                        )}
                        {lines.map((line, i) => {
                            if (line.kind === 'band') {
                                return (
                                    <Typography
                                        key={`b${i}`}
                                        level="body-xs"
                                        sx={{
                                            px: 1.75, pt: 1.25, pb: 0.5, letterSpacing: '0.08em',
                                            textTransform: 'uppercase', color: 'text.tertiary',
                                            fontWeight: 'lg',
                                        }}
                                    >
                                        {line.label}
                                    </Typography>
                                );
                            }
                            index += 1;
                            const here = index;
                            const c = line.cmd;
                            const on = here === cursor;
                            return (
                                <Box
                                    key={c.id}
                                    data-cmd-index={here}
                                    onMouseMove={() => setCursor(here)}
                                    onClick={() => choose(c)}
                                    sx={{
                                        display: 'flex', alignItems: 'center', gap: 1.25,
                                        px: 1.75, py: 0.75, cursor: 'pointer', minWidth: 0,
                                        background: on ? 'var(--joy-palette-primary-softBg)' : 'transparent',
                                        color: on ? 'var(--joy-palette-primary-plainColor)' : 'inherit',
                                    }}
                                >
                                    <Box sx={{ display: 'flex', color: 'text.tertiary', flexShrink: 0 }}>
                                        {KIND_ICON[c.kind]}
                                    </Box>
                                    <Box sx={{ minWidth: 0, flex: 1 }}>
                                        <Typography level="body-sm" noWrap sx={{ color: 'inherit', fontWeight: on ? 'lg' : 'md' }}>
                                            {c.name}
                                        </Typography>
                                        {c.hint && (
                                            <Typography level="body-xs" noWrap sx={{ color: 'text.tertiary' }}>
                                                {c.hint}
                                            </Typography>
                                        )}
                                    </Box>
                                    {c.keys && (
                                        <Chip size="sm" variant="outlined" color="neutral" sx={{ flexShrink: 0 }}>
                                            {c.keys}
                                        </Chip>
                                    )}
                                </Box>
                            );
                        })}
                    </Box>
                    <Box
                        sx={{
                            display: 'flex', gap: 2, px: 1.75, py: 0.75,
                            borderTop: '1px solid', borderColor: 'divider',
                            color: 'text.tertiary', flexWrap: 'wrap',
                        }}
                    >
                        <Typography level="body-xs">↑↓ move</Typography>
                        <Typography level="body-xs">⏎ run</Typography>
                        <Typography level="body-xs">esc close</Typography>
                        <Typography level="body-xs" sx={{ ml: 'auto' }}>
                            {ranked.length} {ranked.length === 1 ? 'command' : 'commands'}
                        </Typography>
                    </Box>
                </Sheet>
            </Box>
        </Modal>
    );
}
