// What the key box asks for under each test.
function keyPlaceholder(when: string): string {
    switch (when) {
        case 'tag': return 'tag';
        case 'tagmatch': return '^M[0-9]+$';
        case 'status': return 'BLOCKED, WAITING';
        default: return 'PROPERTY';
    }
}

// A marker shape, drawn as the chart draws it, for the pickers and the key.
function ShapeSample({ shape, color, size = 14 }: { shape: MarkerShape; color: string; size?: number }) {
    if (shape === 'none') {
        return (
            <svg width={size} height={size} style={{ display: 'block', flexShrink: 0 }}>
                <line x1={size / 2} y1={1} x2={size / 2} y2={size - 1} stroke={color} strokeWidth={1.5} />
            </svg>
        );
    }
    return (
        <svg width={size} height={size} style={{ display: 'block', flexShrink: 0 }}>
            <path d={shapePath(shape, size / 2, size / 2, size / 2 - 1.5)} fill={color} />
        </svg>
    );
}

