// A small drawing of a bar as a rule would have it - fill, shape and outline
// together - for the rule editor and the key. Drawn the way the chart draws
// them, so the sample is a promise about the chart.
let sampleSeq = 0;
function BarSample({ fill = 'solid', shape = 'bar', color, outline, width = 2, w = 34 }: {
    fill?: BarFill; shape?: BarShape; color: string; outline?: string; width?: number; w?: number;
}) {
    const id = React.useMemo(() => `bs${++sampleSeq}`, []);
    const h = 12;
    const paint = fill === 'solid' ? color : fill === 'hollow' ? 'transparent' : `url(#${id})`;
    const edge = outline || (fill === 'hollow' ? color : shade(color, -0.22));
    const sw = outline ? width : fill === 'hollow' ? 1.5 : 1;
    const wash = mix(color, '#ffffff', 0.6);
    return (
        <svg width={w} height={h + 4} style={{ display: 'block', flexShrink: 0, overflow: 'visible' }}>
            <defs>
                {fill === 'hatched' && (
                    <pattern id={id} width="5" height="5" patternTransform="rotate(45)" patternUnits="userSpaceOnUse">
                        <rect width="5" height="5" fill={wash} /><line x1="1.2" y1="0" x2="1.2" y2="5" stroke={color} strokeWidth="2.4" />
                    </pattern>
                )}
                {fill === 'crosshatch' && (
                    <pattern id={id} width="5" height="5" patternTransform="rotate(45)" patternUnits="userSpaceOnUse">
                        <rect width="5" height="5" fill={wash} />
                        <line x1="1" y1="0" x2="1" y2="5" stroke={color} strokeWidth="1.3" />
                        <line x1="0" y1="1" x2="5" y2="1" stroke={color} strokeWidth="1.3" />
                    </pattern>
                )}
                {fill === 'dotted' && (
                    <pattern id={id} width="4" height="4" patternUnits="userSpaceOnUse">
                        <rect width="4" height="4" fill={wash} /><circle cx="2" cy="2" r="1.1" fill={color} />
                    </pattern>
                )}
                {fill === 'striped' && (
                    <pattern id={id} width="5" height="5" patternUnits="userSpaceOnUse">
                        <rect width="5" height="5" fill={wash} /><rect width="2.5" height="5" fill={color} />
                    </pattern>
                )}
            </defs>
            {isSymbolShape(shape) ? (
                <>
                    <rect x={6} y={h / 2} width={w - 7} height={4} rx={2} fill={color} opacity={0.45} />
                    <path d={shapePath(shape, 7, h / 2 + 2, 6)} fill={paint} stroke={edge} strokeWidth={sw} />
                </>
            ) : shape === 'wavy' ? (
                <path d={wavyBarPath(1, 2, w - 2, h, 1.6, 8)} fill={paint} stroke={edge} strokeWidth={sw} />
            ) : (
                <rect x={1} y={2} width={w - 2} height={h} rx={shape === 'pill' ? h / 2 : 3}
                    fill={paint} stroke={edge} strokeWidth={sw} />
            )}
        </svg>
    );
}

// What a rule says, in a few words, for the key beside the controls.
function ruleText(r: { when: string; key: string; value?: string }): string {
    switch (r.when) {
        case 'tag': return `:${r.key}:`;
        case 'tagmatch': return `tag ~ ${r.key}`;
        case 'status': return r.key;
        case 'has': return `has ${r.key}`;
        case 'unscheduled': return 'no date';
        case 'done': return 'done';
    }
    return `${r.key} = ${r.value || ''}`;
}

