// The gantt chart drawn by vis-timeline.
//
// The one of the four that is a real timeline rather than a picture of a
// schedule: it scrolls and zooms over the calendar with the mouse, stacks a
// lane's tasks into collapsible groups, and drags items with the library's own
// handles rather than ones we drew. What it has no notion of is a dependency,
// so the arrows are ours - drawn on an overlay from where vis has put the boxes,
// and redrawn whenever it says it has moved them.
//
// Like the react chart, nothing here writes. A drag ends in a callback and the
// page turns it into an org write; vis is told to put the item back where it
// was, and the refetch afterwards is what actually moves it. That way a write
// that fails leaves the chart telling the truth.

import * as React from 'react';
import { Timeline, TimelineOptions } from 'vis-timeline/esnext';
import { DataSet } from 'vis-data/esnext';
import 'vis-timeline/styles/vis-timeline-graph2d.css';
import {
    GanttModel, GanttTask, GanttMarker, startOfDay, dayKey, daySpan, SHAPE_GLYPH,
    BarRule, BarFill, PLAIN_BAR, barStyleFor, isSymbolShape, TaskHealth,
} from '../gantt';
import { HEALTH_COLOR } from './ReactGantt';
import { GanttColors, MarkerLook } from './ReactGantt';
import { ColorScheme } from '../ganttcolor';
import {
    barGradientCss, shade, contrastText, legibleOn, veilOn, mix, categorical,
    FONT_UI, NUMERIC, TYPE,
} from '../ganttstyle';

const DAY_MS = 86400000;

// How much of the page shows through an implied bar. Used twice: once as the
// item's opacity, once to work out what its label is actually sitting on.
const IMPLIED_WASH = 0.45;

function esc(s: string): string {
    return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// One line about whatever the pointer is over: the words vis would have put in
// a floating tooltip, for the line above the chart that shows them instead.
function describe(id: string, model: GanttModel): string {
    if (!id) return '';
    if (id.indexOf('sum:') === 0) {
        const name = id.slice(4);
        const sec = model.sections.find(x => x.name === name);
        const drawn = sec ? sec.tasks.filter(t => !t.mark) : [];
        if (drawn.length === 0) return '';
        let lo = drawn[0].start;
        let hi = drawn[0].end;
        for (const t of drawn) {
            if (t.start < lo) lo = t.start;
            if (t.end > hi) hi = t.end;
        }
        return `${name || 'main'} \u00b7 ${drawn.length} task${drawn.length === 1 ? '' : 's'}`
            + ` \u00b7 ${dayKey(lo)} \u2192 ${dayKey(hi)}`;
    }
    const t = model.tasks.find(x => x.id === id);
    if (!t) return '';
    const bits = [t.name];
    if (t.status) bits.push(t.status);
    bits.push(`${dayKey(t.start)} \u2192 ${dayKey(t.end)}`);
    if (!t.milestone) {
        const d = t.plannedDays !== null && t.plannedDays !== undefined ? t.plannedDays : t.days;
        bits.push(`${d % 1 === 0 ? d : d.toFixed(1)}d`);
    }
    if (t.resource) bits.push(t.resource);
    if (t.percent) bits.push(`${t.percent}% done`);
    return bits.join(' \u00b7 ');
}

// Whole days. vis will happily hand back 14:37 on a drag, and a date nobody
// chose is not what a bar on a day-scale chart means.
function snapDay(d: Date): Date {
    const t = new Date(d.getTime());
    return t.getHours() >= 12
        ? startOfDay(new Date(t.getTime() + DAY_MS))
        : startOfDay(t);
}

export default function VisGantt({
    model,
    colors,
    scheme,
    selected,
    readOnly,
    onSelect,
    onMove,
    onResize,
    onSection,
    onAdd,
    onDelete,
    onLink,
    markers,
    markerLook,
    barRules,
    critical,
    healthOf,
    onBarMenu,
}: {
    model: GanttModel;
    colors: GanttColors;
    // What a bar's colour means, chosen from the toolbar.
    scheme: ColorScheme;
    selected?: string;
    readOnly?: boolean;
    onSelect?: (t: GanttTask) => void;
    onMove?: (t: GanttTask, start: Date) => void;
    onResize?: (t: GanttTask, days: number) => void;
    onSection?: (t: GanttTask, section: string) => void;
    onAdd?: (start: Date, section: string) => void;
    onDelete?: (t: GanttTask) => void;
    // Dragged from one bar's end handle onto another bar: the one dropped on is
    // the one that waits, exactly as in the svg chart.
    onLink?: (waits: GanttTask, on: GanttTask) => void;
    // Lines down the chart from the view's marker query, as vis custom times.
    markers?: GanttMarker[];
    markerLook?: MarkerLook;
    // Outline, fill and shape for the bars of the headings these rules match.
    barRules?: BarRule[];
    // The critical path's task ids, haloed.
    critical?: Set<string>;
    // Overdue and slipping, tinted and said in the readout line.
    healthOf?: (t: GanttTask) => TaskHealth | null;
    onBarMenu?: (t: GanttTask, x: number, y: number) => void;
}) {
    const boxRef = React.useRef<HTMLDivElement>(null);
    const wrapRef = React.useRef<HTMLDivElement>(null);
    const overlayRef = React.useRef<SVGSVGElement>(null);
    // The bar the pointer is over, and the link being dragged off one of its
    // ends. Both are refs rather than state: they change on every mouse move
    // and the overlay is redrawn imperatively anyway, so putting them through
    // react would re-render the whole timeline to move a circle 3px.
    const timelineRef = React.useRef<Timeline | null>(null);
    // The callbacks change on every render; vis keeps the handlers it was given
    // at construction, so they are read through a ref instead of rebuilding the
    // timeline (which would lose the window the user had scrolled to).
    const hoverRef = React.useRef<string>('');
    // What the line above the chart is saying. State rather than a ref, because
    // unlike the handles it is drawn by react.
    const [readout, setReadout] = React.useState<string>('');
    const linkRef = React.useRef<{ from: string; side: 'left' | 'right' } | null>(null);
    const pointerRef = React.useRef<{ x: number; y: number } | null>(null);
    const live = React.useRef({ model, onSelect, onMove, onResize, onSection, onAdd, onDelete, onLink, readOnly, onBarMenu, healthOf });
    live.current = { model, onSelect, onMove, onResize, onSection, onAdd, onDelete, onLink, readOnly, onBarMenu, healthOf };

    // --- the arrows vis does not draw --------------------------------------
    //
    // Positions are measured, not calculated: vis places items with a css
    // transform rather than by laying them out, so `offsetLeft` on one of its
    // boxes is 0 and the arrows all came out stacked in the top corner. Every
    // box is asked where it actually is, relative to the scrolling centre panel
    // the overlay is pinned over.
    const drawOverlay = React.useCallback(() => {
        const svg = overlayRef.current;
        const tl = timelineRef.current as any;
        if (!svg || !tl || !tl.itemSet) return;
        const items = tl.itemSet.items;
        const frame: HTMLElement | null = tl.dom?.center;
        if (!frame) return;

        // Everything is measured against the wrapper the overlay is pinned to,
        // not against the panel: the svg's position is react's to set, and an
        // imperative left/top here is wiped out by the next render.
        const wrap = wrapRef.current;
        if (!wrap) return;
        const wr = wrap.getBoundingClientRect();
        const fr = frame.getBoundingClientRect();
        svg.setAttribute('width', String(wr.width));
        svg.setAttribute('height', String(wr.height));
        while (svg.lastChild) svg.removeChild(svg.lastChild);

        const box = (id: string): { x: number; y: number; w: number; h: number } | null => {
            const it = items[id];
            const el: HTMLElement | undefined = it?.dom?.box || it?.dom?.point;
            if (!el || !el.isConnected) return null;
            const r = el.getBoundingClientRect();
            if (r.width === 0 && r.height === 0) return null;
            return { x: r.left - wr.left, y: r.top - wr.top, w: r.width, h: r.height };
        };

        const ns = 'http://www.w3.org/2000/svg';
        const defs = document.createElementNS(ns, 'defs');
        // Clipped to the scrolling panel, so an arrow reaching a task that is
        // off the side of the window is not drawn across the lane names.
        const clip = document.createElementNS(ns, 'clipPath');
        clip.setAttribute('id', 'vg-clip');
        const cr = document.createElementNS(ns, 'rect');
        cr.setAttribute('x', String(fr.left - wr.left));
        cr.setAttribute('y', String(fr.top - wr.top));
        cr.setAttribute('width', String(fr.width));
        cr.setAttribute('height', String(fr.height));
        clip.appendChild(cr);
        defs.appendChild(clip);
        const mk = document.createElementNS(ns, 'marker');
        mk.setAttribute('id', 'vg-arrow');
        mk.setAttribute('markerWidth', '7'); mk.setAttribute('markerHeight', '7');
        mk.setAttribute('refX', '6'); mk.setAttribute('refY', '3.5');
        mk.setAttribute('orient', 'auto');
        const head = document.createElementNS(ns, 'path');
        head.setAttribute('d', 'M0,0 L7,3.5 L0,7 z');
        head.setAttribute('fill', colors.text);
        head.setAttribute('fill-opacity', '0.55');
        mk.appendChild(head);
        defs.appendChild(mk);
        svg.appendChild(defs);

        // The two handles on the bar under the pointer. vis has no notion of a
        // dependency at all, so this is our own drag layer: circles just off
        // each end of the hovered bar, dragged onto another bar to say which
        // waits for which. They sit *outside* the bar so they never cover vis's
        // own resize grips, and the overlay ignores the pointer everywhere
        // except on the circles themselves.
        const handleFor = (id: string, side: 'left' | 'right') => {
            const b = box(id);
            if (!b) return;
            const cx = side === 'left' ? b.x - 9 : b.x + b.w + 9;
            const cy = b.y + b.h / 2;
            const c = document.createElementNS(ns, 'circle');
            c.setAttribute('cx', String(cx));
            c.setAttribute('cy', String(cy));
            c.setAttribute('r', '4.5');
            c.setAttribute('fill', colors.background);
            c.setAttribute('stroke', colors.text);
            c.setAttribute('stroke-opacity', '0.65');
            c.setAttribute('stroke-width', '1.2');
            c.setAttribute('style', 'pointer-events: all; cursor: crosshair;');
            c.addEventListener('pointerdown', ev => {
                ev.preventDefault();
                ev.stopPropagation();
                linkRef.current = { from: id, side };
                drawOverlay();
            });
            svg.appendChild(c);
        };

        for (const t of live.current.model.tasks) {
            for (const depId of t.after) {
                const a = box(depId);
                const b = box(t.id);
                if (!a || !b) continue;
                const x1 = a.x + a.w, y1 = a.y + a.h / 2;
                const x2 = b.x, y2 = b.y + b.h / 2;
                const gap = 12;
                const d = x2 - x1 > gap * 2
                    ? `M${x1},${y1} H${x1 + gap} V${y2} H${x2}`
                    : `M${x1},${y1} H${x1 + gap} V${y1 + (y2 > y1 ? a.h : -a.h)} H${x2 - gap} V${y2} H${x2}`;
                const path = document.createElementNS(ns, 'path');
                path.setAttribute('d', d);
                path.setAttribute('fill', 'none');
                path.setAttribute('stroke', colors.text);
                path.setAttribute('stroke-opacity', '0.45');
                path.setAttribute('stroke-width', '1.2');
                path.setAttribute('marker-end', 'url(#vg-arrow)');
                path.setAttribute('clip-path', 'url(#vg-clip)');
                svg.appendChild(path);
            }
        }

        // A label wider than its bar. vis clips it, which turns a task name into
        // a word broken off mid-syllable; letting it spill instead means it is
        // then sitting on the page rather than on the bar, so it also has to
        // change colour to the page's ink. Measured here because only the
        // rendered box knows how wide it came out.
        const pageInk = legibleOn(colors.text, colors.background);
        for (const id of Object.keys(items)) {
            const el: HTMLElement | undefined = items[id]?.dom?.box;
            const content = el ? (el.querySelector('.vis-item-content') as HTMLElement | null) : null;
            if (!el || !content) continue;
            if (el.classList.contains('vg-summary')) continue;
            const fits = content.scrollWidth <= el.clientWidth - 2;
            el.classList.toggle('vg-spill', !fits);
            content.style.color = fits ? '' : pageInk;
        }

        const drag = linkRef.current;
        const hovered = hoverRef.current;
        if (!live.current.readOnly && !drag && hovered) {
            const t = live.current.model.tasks.find(x => x.id === hovered);
            if (t && !t.implied) {
                handleFor(hovered, 'left');
                handleFor(hovered, 'right');
            }
        }
        if (drag) {
            const b = box(drag.from);
            const to = pointerRef.current;
            if (b && to) {
                const x1 = drag.side === 'left' ? b.x - 9 : b.x + b.w + 9;
                const y1 = b.y + b.h / 2;
                const rubber = document.createElementNS(ns, 'path');
                rubber.setAttribute('d', `M${x1},${y1} L${to.x},${to.y}`);
                rubber.setAttribute('stroke', colors.taskActive);
                rubber.setAttribute('stroke-width', '1.5');
                rubber.setAttribute('stroke-dasharray', '4 3');
                rubber.setAttribute('fill', 'none');
                svg.appendChild(rubber);
            }
        }
    }, [colors.text, colors.background, colors.taskActive]);

    // --- build it once -----------------------------------------------------
    React.useEffect(() => {
        if (!boxRef.current) return;
        const items = new DataSet<any>([]);
        const groups = new DataSet<any>([]);

        const find = (id: any): GanttTask | undefined =>
            live.current.model.tasks.find(t => t.id === String(id));

        const options: TimelineOptions = {
            stack: false,
            groupOrder: 'order',
            orientation: { axis: 'top', item: 'top' },
            margin: { item: { horizontal: 0, vertical: 6 }, axis: 4 },
            zoomMin: 1000 * 60 * 60 * 24 * 3,
            zoomMax: 1000 * 60 * 60 * 24 * 365 * 6,
            showCurrentTime: true,
            selectable: true,
            multiselect: false,
            // No floating tooltip. vis hangs one off the pointer, which on a
            // chart made of horizontal bars lands squarely on the neighbouring
            // ones - you cover what you are comparing against in order to read
            // what you are pointing at. The same words go in a line above the
            // chart instead, which is always in the same place and can never be
            // in the way of a bar.
            tooltip: { followMouse: false, overflowMethod: 'none' },
            // Whole days, on the drag as well as at the end of it, so the bar
            // under the pointer is the bar that will be written.
            snap: (date: Date) => snapDay(date),
            editable: {
                add: true,
                updateTime: true,
                updateGroup: true,
                remove: true,
                overrideItems: false,
            },
            onMove: (item: any, callback: (i: any) => void) => {
                const t = find(item.id);
                const c = live.current;
                if (!t || c.readOnly || t.implied) { callback(null); return; }
                const start = snapDay(new Date(item.start));
                const end = item.end ? snapDay(new Date(item.end)) : start;
                const wasStart = startOfDay(t.start);
                const days = Math.max(0.5, Math.round((end.getTime() - start.getTime()) / DAY_MS));
                const movedGroup = String(item.group) !== `task:${t.id}`;

                if (movedGroup && c.onSection) {
                    const sec = String(item.group).replace(/^sec:/, '');
                    c.onSection(t, sec);
                } else {
                    if (start.getTime() !== wasStart.getTime() && c.onMove) c.onMove(t, start);
                    const wasDays = t.plannedDays ?? t.days;
                    if (!t.milestone && Math.abs(days - wasDays) > 0.01 && c.onResize) c.onResize(t, days);
                }
                // Always refused: the refetch after the write is what moves it,
                // so a failed write cannot leave the chart lying.
                callback(null);
            },
            onRemove: (item: any, callback: (i: any) => void) => {
                const t = find(item.id);
                const c = live.current;
                if (t && !c.readOnly && !t.implied && c.onDelete) c.onDelete(t);
                callback(null);
            },
            onAdd: (item: any, callback: (i: any) => void) => {
                const c = live.current;
                if (!c.readOnly && c.onAdd) {
                    c.onAdd(snapDay(new Date(item.start)), String(item.group || '').replace(/^sec:/, ''));
                }
                callback(null);
            },
        };

        const tl = new Timeline(boxRef.current, items as any, groups as any, options);
        timelineRef.current = tl;
        tl.on('select', (props: any) => {
            const id = props.items && props.items[0];
            const t = id ? find(id) : null;
            if (t && live.current.onSelect) live.current.onSelect(t);
        });
        tl.on('changed', drawOverlay);
        // A right click on a bar opens the chart's own menu, not the
        // browser's.
        tl.on('contextmenu', (props: any) => {
            const t = props && props.item ? find(props.item) : null;
            const c = live.current;
            if (!t || t.implied || !c.onBarMenu) return;
            props.event.preventDefault();
            c.onBarMenu(t, props.event.clientX, props.event.clientY);
        });
        // Which bar the handles belong to.
        tl.on('itemover', (props: any) => {
            const id = props && props.item ? String(props.item) : '';
            hoverRef.current = id;
            {
                // The readout says what trouble a bar is in, since the tint
                // alone would be colour as the only way of telling.
                const t = live.current.model.tasks.find(x => x.id === id);
                const h = t && live.current.healthOf ? live.current.healthOf(t) : null;
                setReadout(describe(id, live.current.model) + (h ? ` \u00b7 ${h.note}` : ''));
            }
            drawOverlay();
        });
        tl.on('itemout', () => {
            // Left alone mid-drag: the pointer leaves the bar the moment the
            // drag starts, and taking the handles away then would cut the line
            // the user is still drawing.
            if (linkRef.current) return;
            hoverRef.current = '';
            setReadout('');
            drawOverlay();
        });

        // The link drag itself. On the window rather than on the svg, because
        // the pointer spends the whole drag over vis's own items.
        const onPointerMove = (ev: PointerEvent) => {
            if (!linkRef.current) return;
            const wrap = wrapRef.current;
            if (!wrap) return;
            const r = wrap.getBoundingClientRect();
            pointerRef.current = { x: ev.clientX - r.left, y: ev.clientY - r.top };
            drawOverlay();
        };
        const onPointerUp = (ev: PointerEvent) => {
            const drag = linkRef.current;
            if (!drag) return;
            linkRef.current = null;
            pointerRef.current = null;
            // What was under the pointer when it was let go. The overlay ignores
            // the pointer, so this finds the vis item itself.
            const el = document.elementFromPoint(ev.clientX, ev.clientY);
            const itemEl = el ? (el as HTMLElement).closest('.vis-item') : null;
            const c = live.current;
            let ontoId = '';
            if (itemEl) {
                const items = (timelineRef.current as any)?.itemSet?.items || {};
                for (const id of Object.keys(items)) {
                    const dom = items[id]?.dom;
                    if (dom && (dom.box === itemEl || dom.point === itemEl)) { ontoId = id; break; }
                }
            }
            const from = c.model.tasks.find(t => t.id === drag.from);
            const onto = ontoId ? c.model.tasks.find(t => t.id === ontoId) : null;
            if (from && onto && onto.id !== from.id && !onto.implied && !c.readOnly && c.onLink) {
                // A handle on the right says "this one comes first", a handle on
                // the left says "this one comes after" - so which of the two is
                // the waiter depends on the end it was dragged from.
                if (drag.side === 'right') c.onLink(onto, from);
                else c.onLink(from, onto);
            }
            drawOverlay();
        };
        window.addEventListener('pointermove', onPointerMove);
        window.addEventListener('pointerup', onPointerUp);

        return () => {
            window.removeEventListener('pointermove', onPointerMove);
            window.removeEventListener('pointerup', onPointerUp);
            tl.destroy();
            timelineRef.current = null;
        };
    }, [drawOverlay]);

    // --- markers -----------------------------------------------------------
    // vis's custom time bars, one per marker. Declared after the effect that
    // builds the timeline and keyed on the same thing, so a rebuilt timeline
    // gets its markers back. The ids of the last set are kept to take them
    // off again; a timeline that was rebuilt never had them, hence the try.
    const markerIds = React.useRef<string[]>([]);
    React.useEffect(() => {
        const tl = timelineRef.current as any;
        if (!tl) return;
        for (const id of markerIds.current) {
            try { tl.removeCustomTime(id); } catch { /* not on this timeline */ }
        }
        markerIds.current = [];
        (markers || []).forEach((m, i) => {
            const id = `wg-marker-${i}`;
            tl.addCustomTime(m.date, id);
            tl.setCustomTimeTitle(`${m.name}  ${dayKey(m.date)}${m.end ? ` → ${dayKey(new Date(m.end.getTime() - 1))}` : ''}`, id);
            // vis puts the label in as html, so the name is escaped; the
            // shape goes in as its character, vis having no way to draw one.
            const glyph = m.shape && m.shape !== 'none' ? SHAPE_GLYPH[m.shape] + ' ' : '';
            tl.setCustomTimeMarker(esc(glyph + m.name), id, false);
            markerIds.current.push(id);
        });
    }, [markers, drawOverlay]);

    // --- keep it fed -------------------------------------------------------
    React.useEffect(() => {
        const tl = timelineRef.current as any;
        if (!tl) return;

        const groups: any[] = [];
        const items: any[] = [];
        let order = 0;
        let laneIndex = 0;
        for (const sec of model.sections) {
            const drawn = sec.tasks.filter(t => !t.mark);
            if (drawn.length === 0) continue;
            const secId = `sec:${sec.name}`;
            // `treeLevel` is not decoration: without it vis cannot work out how
            // deep a nested group sits, marks it
            // `vis-group-level-unknown-but-gte1`, and draws a **red border**
            // round every row to say so. That red was vis telling us the group
            // data was under-specified, so it is answered rather than hidden.
            groups.push({
                id: secId, content: sec.name || 'main', order: order++,
                nestedGroups: drawn.map(t => `task:${t.id}`),
                showNested: true,
                treeLevel: 1,
            });
            // The lane's own line: an I-beam across everything inside it, drawn
            // on the heading row itself. A lane heading otherwise says nothing
            // about *when* its work happens, which is the one question the chart
            // is for - and when the lane is folded shut it is all that is left
            // of it. Muted and in the lane's own hue so it reads as the lane
            // rather than as one more task: the caps are the item's left and
            // right borders, the beam is a band in its background.
            let lo: Date | null = null;
            let hi: Date | null = null;
            for (const t of drawn) {
                if (!lo || t.start < lo) lo = t.start;
                if (!hi || t.end > hi) hi = t.end;
            }
            if (lo && hi) {
                const beam = mix(categorical(laneIndex), colors.background, 0.34);
                // How long the lane runs, written into the beam itself. The
                // content sits on the chart's own ground (see the css below),
                // so the line breaks around the number rather than striking
                // through it - which is what makes it read as an I-beam with a
                // measurement on it rather than as a bar with text over it.
                const span = daySpan(lo, hi);
                items.push({
                    id: `sum:${sec.name}`,
                    group: secId,
                    start: lo,
                    end: hi,
                    type: 'range',
                    content: `${span}d`,
                    selectable: false,
                    editable: false,
                    className: 'vg-summary',
                    style: `background: linear-gradient(to bottom, transparent 42%, ${beam} 42%,`
                        + ` ${beam} 58%, transparent 58%);`
                        + `border-left: 2px solid ${beam}; border-right: 2px solid ${beam};`
                        + `border-top: none; border-bottom: none; border-radius: 0;`,
                });
            }
            laneIndex += 1;

            for (const t of drawn) {
                groups.push({
                    id: `task:${t.id}`, content: esc(t.name), order: order++, treeLevel: 2,
                });
                const color = scheme.color(t);
                const st = t.implied ? PLAIN_BAR : barStyleFor(t, barRules || []);
                const ring = st.outline;
                const hollow = st.fill === 'hollow';
                const patterned = st.fill !== 'solid' && !hollow;
                const wash = mix(color, colors.background, 0.6);
                const edge = ring ? ring.color : hollow ? color : shade(color, -0.22);
                // An implied bar is washed out towards the page (see
                // .vg-implied below), so its label is read against the blend
                // rather than against the colour itself - picking the ink on
                // the undiluted colour is how the svg chart ended up with black
                // text on a near-black ground in dark mode.
                const ground = t.implied ? mix(color, colors.background, IMPLIED_WASH) : color;
                const pct = Math.max(0, Math.min(100, t.percent || 0));
                // How much of it is done, laid over the gradient as a second
                // background image rather than as an element inside the item:
                // vis sanitises item *content* and strips the class and style
                // off anything put in there - which is why the label used to
                // come out at the page's own 16px and this overlay never showed
                // up at all. An item's `style` is not content and survives.
                const isCrit = !!critical && critical.has(t.id);
                const health = healthOf ? healthOf(t) : null;
                const done = pct > 0
                    ? `linear-gradient(90deg, rgba(0,0,0,0.22) 0 ${pct}%, rgba(0,0,0,0) ${pct}%), `
                    : '';
                // vis cannot draw a bar as a symbol, so a diamond, circle or
                // star task says which it is in front of its name; a pill gets
                // round ends, and a wave stays a bar - the svg chart draws it.
                const glyph = isSymbolShape(st.shape) ? SHAPE_GLYPH[st.shape] + ' ' : '';
                // What the label sits on: the wash under a pattern, with a
                // halo of it so the stripes behind a letter do not cut it up;
                // the page under a hollow bar.
                const labelGround = patterned ? wash : hollow ? colors.background : ground;
                // On a hollow bar the done part is filled in with the bar's
                // own colour, as the svg chart does, rather than darkened.
                const background = hollow
                    ? `background-color:${colors.background}; background-image:${pct > 0
                        ? `linear-gradient(90deg, ${color}59 0 ${pct}%, transparent ${pct}%)`
                        : 'none'};`
                    : patterned
                        ? (() => {
                            const f = fillCss(st.fill, color, wash);
                            const images = done ? [done.replace(/, $/, ''), ...f.images] : f.images;
                            const sizes = done ? ['auto', ...f.sizes] : f.sizes;
                            return `background-color:${wash}; background-image:${images.join(', ')}; `
                                + `background-size:${sizes.join(', ')};`;
                        })()
                        : `background-color:${color}; background-image:${done}${barGradientCss(color)};`;
                items.push({
                    id: t.id,
                    group: `task:${t.id}`,
                    content: esc(glyph + t.name),
                    start: t.start,
                    end: t.milestone ? undefined : t.end,
                    type: t.milestone ? 'point' : 'range',
                    editable: readOnly || t.implied ? false : { updateTime: true, updateGroup: true, remove: true },
                    className: t.implied ? 'vg-implied' : '',
                    // The gradient is a background *image*, so vis's own
                    // background-color stays underneath it as the fallback.
                    style: background
                        + `border-color:${edge}; color:${contrastText(labelGround)};`
                        + (patterned ? `text-shadow: 0 0 2px ${wash}, 0 0 3px ${wash}, 0 0 4px ${wash};` : '')
                        + (ring ? `border-width:${ring.width}px;` : hollow ? 'border-width:1.75px;' : '')
                        + (st.shape === 'pill' ? 'border-radius:999px;' : '')
                        // The critical path is a halo, as in the svg chart; a
                        // task in trouble gets a band of its colour along the
                        // top. Both are shadows, which take no room and so
                        // move nothing vis has measured.
                        + ((isCrit || health)
                            ? `box-shadow:${[
                                isCrit ? `0 0 0 3px ${colors.taskCrit}55` : '',
                                health ? `inset 0 3px 0 ${HEALTH_COLOR[health.kind]}` : '',
                            ].filter(Boolean).join(', ')};`
                            : ''),
                });
            }
        }
        // Range markers are a band across every lane, as vis background items;
        // the line and label at their start are the custom time below.
        (markers || []).forEach((m, i) => {
            if (!m.end) return;
            const c = m.color || (markerLook && markerLook.color) || '#8e44ad';
            items.push({
                id: `wg-band-${i}`, start: m.date, end: m.end, type: 'background',
                content: '', style: `background-color:${c}1f;`,
            });
        });
        // The marks (mermaid's `vert`) are vis's own custom time bars.
        for (const m of model.tasks.filter(t => t.mark)) {
            items.push({
                id: m.id, group: groups.length > 0 ? groups[0].id : undefined,
                content: esc(m.name), start: m.start, type: 'background',
                style: `background-color:${colors.taskCrit}33;`,
            });
        }

        tl.setGroups(new DataSet(groups) as any);
        tl.setItems(new DataSet(items) as any);
        if (selected) tl.setSelection([selected]); else tl.setSelection([]);
        window.setTimeout(drawOverlay, 0);
    }, [model, colors, scheme, readOnly, selected, drawOverlay, barRules, critical, healthOf, markers, markerLook]);

    // Fit the whole plan the first time there is one to fit.
    const fitted = React.useRef(false);
    React.useEffect(() => {
        const tl = timelineRef.current;
        if (!tl || fitted.current || model.tasks.length === 0) return;
        fitted.current = true;
        tl.setWindow(
            new Date(model.start.getTime() - DAY_MS * 2),
            new Date(model.end.getTime() + DAY_MS * 2),
            { animation: false },
        );
    }, [model]);

    const ink = legibleOn(colors.text, colors.background);
    return (
        <div ref={wrapRef} style={{ position: 'relative' }}>
            <VisStyles colors={colors} markerLook={markerLook} markers={markers} />
            {/* The readout: what a floating tooltip would have said, in a line
                that is always in the same place. Its height is reserved whether
                or not it has anything to say, so the chart does not jump every
                time the pointer crosses a bar. */}
            <div
                style={{
                    minHeight: 18,
                    marginBottom: 2,
                    color: ink,
                    opacity: readout ? 0.85 : 0,
                    fontFamily: FONT_UI,
                    fontSize: `${TYPE.visBar.size}px`,
                    letterSpacing: '0.02em',
                    fontVariantNumeric: NUMERIC,
                    whiteSpace: 'nowrap',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                }}
            >
                {readout || '\u00a0'}
            </div>
            <div ref={boxRef} style={{ position: 'relative' }} />
            <svg ref={overlayRef} style={{ position: 'absolute', left: 0, top: 0, pointerEvents: 'none' }} />
        </div>
    );
}

// The handful of styles vis needs to look like the rest of the app. Theming it
// properly means overriding its stylesheet, and these are the rules that matter:
// the page's own colours, and the two spans the items are built out of.
// A bar fill as css background layers over a wash of the bar's own colour,
// matching the svg chart's patterns: the images and, layer for layer, their
// sizes. The sizes are their own property because vis re-serialises an item's
// style and drops the `/ size` part of a `background` shorthand - the dots
// then grew to one per bar. Hollow and solid are not patterns and are handled
// where the item is built.
function fillCss(fill: BarFill, color: string, wash: string): { images: string[]; sizes: string[] } {
    switch (fill) {
        case 'hatched':
            return { images: [`repeating-linear-gradient(45deg, ${color} 0 2.2px, ${wash} 2.2px 5.5px)`], sizes: ['auto'] };
        case 'crosshatch':
            return {
                images: [
                    `repeating-linear-gradient(45deg, ${color} 0 1.2px, transparent 1.2px 5px)`,
                    `repeating-linear-gradient(-45deg, ${color} 0 1.2px, ${wash} 1.2px 5px)`,
                ],
                sizes: ['auto', 'auto'],
            };
        case 'dotted':
            return {
                images: [`radial-gradient(circle, ${color} 0 1.3px, transparent 1.6px)`, `linear-gradient(${wash}, ${wash})`],
                sizes: ['5px 5px', 'auto'],
            };
        case 'striped':
            return { images: [`repeating-linear-gradient(90deg, ${color} 0 3px, ${wash} 3px 6px)`], sizes: ['auto'] };
    }
    return { images: [], sizes: [] };
}

// A marker line's dash as a css background, since a border can say dashed and
// dotted but not dash-dot. Measured in the line's own width, as the svg chart's
// dashes are.
function markerBackground(look: MarkerLook): string {
    const c = look.color;
    const w = Math.max(1, look.width);
    switch (look.style) {
        case 'dashed':
            return `repeating-linear-gradient(to bottom, ${c} 0 ${w * 4}px, transparent ${w * 4}px ${w * 7}px)`;
        case 'dotted':
            return `repeating-linear-gradient(to bottom, ${c} 0 ${w}px, transparent ${w}px ${w * 3}px)`;
        case 'dashdot':
            return `repeating-linear-gradient(to bottom, ${c} 0 ${w * 5}px, transparent ${w * 5}px ${w * 7}px, `
                + `${c} ${w * 7}px ${w * 8}px, transparent ${w * 8}px ${w * 10}px)`;
    }
    return c;
}

function VisStyles({ colors, markerLook, markers }: { colors: GanttColors; markerLook?: MarkerLook; markers?: GanttMarker[] }) {
    // Every colour below is worked out against the chart's own ground, so a
    // dark background gets light labels and a light one dark, whatever the
    // seven colours under the chart have been set to.
    const ink = legibleOn(colors.text, colors.background);
    return (
        <style>{`
                ${markerLook ? `
                /* The marker lines. vis makes custom times draggable; these are
                   read from the files, so the drag handle is switched off. */
                .vis-custom-time {
                    background: ${markerBackground(markerLook)};
                    width: ${Math.max(1, markerLook.width)}px; cursor: default;
                }
                .vis-custom-time > div { pointer-events: none; cursor: default; }
                .vis-custom-time .vis-custom-time-marker {
                    background: ${markerLook.color};
                    color: ${contrastText(markerLook.color)};
                    font-family: ${FONT_UI}; font-size: ${TYPE.note.size}px;
                    padding: 1px 4px; border-radius: 2px;
                }
                ${(markers || []).map((m, i) => (m.color || m.style || m.width) ? `
                /* A rule gave this marker a colour of its own. vis names each
                   bar after its id, which is what lets one be singled out. */
                .vis-custom-time.wg-marker-${i} {
                    background: ${markerBackground({ color: m.color || markerLook.color, style: m.style || markerLook.style, width: m.width || markerLook.width })};
                    width: ${Math.max(1, m.width || markerLook.width)}px;
                }
                .vis-custom-time.wg-marker-${i} .vis-custom-time-marker {
                    background: ${m.color || markerLook.color}; color: ${contrastText(m.color || markerLook.color)};
                }` : '').join('')}` : ''}
                .vis-timeline {
                    border: none; font-family: ${FONT_UI};
                    color: ${ink}; background: ${colors.background};
                }
                .vis-panel, .vis-time-axis .vis-text { color: ${ink}; }
                /* vis paints the nested rows #f5f5f5 from its own stylesheet, and
                   that rule beats a plain .vis-label one - which is what left the
                   whole name column white on a dark chart. Both kinds are named. */
                .vis-labelset .vis-label,
                .vis-labelset .vis-label.vis-nesting-group {
                    color: ${ink}; background: ${colors.background};
                }
                .vis-labelset .vis-label.vis-nested-group {
                    color: ${ink}; background: ${veilOn(colors.background, 0.035)};
                }
                .vis-foreground .vis-group,
                .vis-panel.vis-background, .vis-panel.vis-left, .vis-panel.vis-right {
                    background: ${colors.background};
                }
                /* A lane name is a heading; a task name is a label. */
                .vis-labelset .vis-label.vis-nesting-group > .vis-inner {
                    font-size: 10.5px; font-weight: 700; letter-spacing: 0.14em;
                    text-transform: uppercase; opacity: 0.72;
                }
                .vis-labelset .vis-label .vis-inner {
                    font-size: 12px; font-weight: 500; letter-spacing: 0.005em; opacity: 0.92;
                }
                .vis-panel.vis-center, .vis-panel.vis-left, .vis-panel.vis-right,
                .vis-panel.vis-top, .vis-panel.vis-bottom { border-color: ${veilOn(colors.background, 0.2)}; }
                .vis-grid.vis-vertical { border-left-style: dotted; }
                .vis-grid.vis-minor { border-color: ${veilOn(colors.background, 0.13)}; }
                .vis-grid.vis-major {
                    border-color: ${veilOn(colors.background, 0.18)};
                    border-left-style: solid;
                }
                .vis-grid.vis-saturday, .vis-grid.vis-sunday { background: ${veilOn(colors.background, 0.055)}; }
                .vis-grid.vis-odd { background: ${veilOn(colors.background, 0.03)}; }
                /* The row rules. vis draws these solid #bfbfbf from its own
                   stylesheet, which on a dark chart is a set of white stripes
                   across it - and even on a light one they are louder than the
                   bars they separate. Dotted and faint: enough to follow a row
                   across the chart, not enough to look at. */
                .vis-labelset .vis-label,
                .vis-foreground .vis-group {
                    border-bottom: 1px dotted ${veilOn(colors.background, 0.16)};
                }
                .vis-labelset .vis-label.vis-nesting-group,
                .vis-foreground .vis-group.vis-nesting-group {
                    border-bottom: 1px solid ${veilOn(colors.background, 0.1)};
                }
                /* Both of these have to name the item's *variant*: vis's own
                   rules are on .vis-item.vis-range, and a plain .vis-item one
                   loses to them. A bar's corner radius and its thickness are
                   decisions rather than measurements, so they are stated here
                   rather than left to fall out of the text metrics - vis sizes
                   an item off its content box and that came out fatter than a
                   gantt bar wants to be. */
                .vis-item { border-width: 1px; }
                .vis-item.vis-range, .vis-item.vis-box { border-radius: 6px; }
                .vis-item.vis-range { height: 20px; }
                /* Centred by the box rather than by the line height: a line box
                   tall enough to centre the text is also tall enough to have
                   its descenders clipped by the bar's own overflow, which is
                   what was cutting the tail off every "g" and "p". */
                .vis-item.vis-range .vis-item-overflow {
                    display: flex;
                    align-items: center;
                }
                .vis-item.vis-range .vis-item-content { line-height: 1.2; }
                .vis-item.vis-selected {
                    box-shadow: 0 0 0 2px ${legibleOn(colors.text, colors.background)}; z-index: 3;
                }
                /* Faded because the query did not find it - it is only here
                   because something else waits on it. The same fraction is in
                   IMPLIED_WASH, which is what its label's ink is chosen
                   against; change one and change both. */
                .vis-item.vg-implied { opacity: ${1 - IMPLIED_WASH}; border-style: dashed; }
                /* The lane's I-beam: thinner than a bar, unclickable, and out of
                   the way of everything that is one. */
                .vis-item.vis-range.vg-summary {
                    height: 12px;
                    pointer-events: none;
                    box-shadow: none;
                }
                /* The measurement in the middle of the beam, on the chart's own
                   ground so the line breaks around it. Centred rather than
                   left-aligned: it is a caption on the whole span, not a label
                   on its start. */
                .vis-item.vis-range.vg-summary .vis-item-overflow {
                    justify-content: center;
                }
                .vis-item.vis-range.vg-summary .vis-item-content {
                    background: ${colors.background};
                    color: ${legibleOn(colors.text, colors.background)};
                    opacity: 0.7;
                    padding: 0 6px;
                    font-size: 9.5px;
                    font-weight: 600;
                    letter-spacing: 0.08em;
                    font-variant-numeric: ${NUMERIC};
                }
                /* The label is styled on the element vis makes rather than on a
                   span of ours inside it, because a span of ours does not
                   survive vis's sanitiser. Smaller than the page's own text and
                   tighter in the line: a name written along a bar is a caption
                   on a measurement, and at the inherited 16px it was wearing the
                   bar rather than sitting in it. The colour is set per item
                   against that bar's own fill, so nothing here says what colour
                   a name is. */
                /* A name too long for its bar is put just past the end of it
                   rather than chopped off inside it. The colour is swapped to
                   the page's ink at the same time (in the overlay pass, which
                   is what measures the fit), because out here the ground is the
                   chart, not the bar. */
                .vis-item.vg-spill .vis-item-overflow { overflow: visible; }
                .vis-item.vg-spill .vis-item-content {
                    position: absolute;
                    left: 100%;
                    top: 50%;
                    transform: translateY(-50%);
                    padding: 0 0 0 7px;
                }
                .vis-item .vis-item-content {
                    padding: 0 8px;
                    font-size: ${TYPE.visBar.size}px;
                    font-weight: ${TYPE.visBar.weight};
                    letter-spacing: ${TYPE.visBar.spacing};
                    font-variant-numeric: ${NUMERIC};
                }
                .vis-time-axis .vis-text {
                    font-size: 10px; font-weight: 500; letter-spacing: 0.03em;
                    font-variant-numeric: ${NUMERIC}; opacity: 0.65;
                }
                .vis-time-axis .vis-text.vis-major {
                    font-size: 10.5px; font-weight: 600; letter-spacing: 0.06em; opacity: 0.8;
                }
            .vis-current-time { background-color: #e74c3c; }
        `}</style>
    );
}
